<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { api } from '../api/client'
import { useAccountsStore } from '../stores/accounts'
import { useSessionStore } from '../stores/session'
import { exchangeNames, type Exchange, type SystemStatus } from '../types/domain'
import Icon from '../components/Icon.vue'
import EmptyState from '../components/EmptyState.vue'
const accounts = useAccountsStore(), session = useSessionStore()
const status = ref<SystemStatus | null>(null), error = ref('')
const exchanges: Exchange[] = ['binance', 'bitget', 'okx']
const configured = computed(() => accounts.accounts.filter(a => a.credentials_configured).length)
const dependenciesReady = computed(() => !!status.value && Object.values(status.value.checks).every(value => value === 'READY'))
async function refresh(): Promise<void> { error.value = ''; await accounts.refresh(); try { status.value = await api<SystemStatus>('/system/status') } catch (cause) { error.value = cause instanceof Error ? cause.message : '系统状态不可用' } }
onMounted(refresh)
</script>
<template><div class="page-heading"><div><span class="eyebrow">PORTFOLIO OVERVIEW</span><h1>资产总览</h1><p>你好，{{ session.session?.workspace.name }}。先连接账户，建立你的交易视野。</p></div><button class="button secondary" :disabled="accounts.loading" @click="refresh"><Icon name="refresh" :size="16" />刷新状态</button></div><div v-if="error || accounts.error" class="alert error" role="alert">{{ error || accounts.error }}</div><div class="notice"><Icon name="shield" /><div><strong>基础环境已就绪，账户数据等待接入</strong><span>公开行情已可使用；资产与持仓将在只读账户同步完成后显示。</span></div><RouterLink to="/market" class="text-link">查看公开行情 →</RouterLink><span class="pill">只读模式</span></div>
<div class="metrics-grid"><article class="metric-card"><div class="metric-label">总资产净值 <span>USDT</span></div><strong class="metric-value">—</strong><span class="metric-note">尚未同步交易所权益</span></article><article class="metric-card"><div class="metric-label">未实现盈亏 <Icon name="chart" :size="15" /></div><strong class="metric-value">—</strong><span class="metric-note">持仓数据未接入</span></article><article class="metric-card"><div class="metric-label">账户连接配置 <Icon name="link" :size="15" /></div><strong class="metric-value">{{ accounts.error ? '—' : accounts.accounts.length }}<small>个账户</small></strong><span class="metric-note">{{ configured }} 个已保存加密密钥 · 均待验证</span></article><article class="metric-card"><div class="metric-label">基础服务 <Icon name="pulse" :size="15" /></div><strong class="metric-value status-value" :class="{ positive: dependenciesReady }">{{ !status ? '待检查' : dependenciesReady ? '运行正常' : '需要检查' }}</strong><span class="metric-note">数据库 · 数据迁移 · Redis</span></article></div>
<div class="overview-columns"><section class="panel"><div class="panel-heading"><div><h2>资产净值曲线</h2><p>基于账户快照生成，入金与收益分开统计</p></div><span class="tiny-tag">等待 E02</span></div><EmptyState title="连接账户后，开始记录你的净值" description="当前没有可用的交易所权益快照。缺失数据不会被填成 0。" icon="chart"><RouterLink to="/accounts" class="button secondary"><Icon name="plus" :size="16" />配置账户连接</RouterLink></EmptyState></section><section class="panel setup-panel"><div class="panel-heading"><h2>开始使用</h2><span class="muted">接入准备</span></div><div class="setup-step"><span class="step-number done">✓</span><div><strong>建立安全工作空间</strong><p>会话认证、权限和密钥加密</p></div></div><div class="setup-step"><span class="step-number" :class="{ done: accounts.accounts.length > 0 }">{{ accounts.accounts.length > 0 ? '✓' : '2' }}</span><div><strong>添加交易所账户</strong><p>区分模拟、实盘与账户模式</p><RouterLink to="/accounts">管理连接 →</RouterLink></div></div><div class="setup-step"><span class="step-number">3</span><div><strong>验证并同步真实数据</strong><p>公开行情已上线，下一步接入只读账户同步</p></div></div></section></div>
<section class="panel"><div class="panel-heading"><div><h2>交易所连接</h2><p>配置状态与数据同步状态分别记录</p></div><RouterLink to="/accounts" class="text-link">管理账户 →</RouterLink></div><div class="exchange-grid"><article v-for="exchange in exchanges" :key="exchange" class="exchange-card"><div class="exchange-title"><span class="exchange-monogram" :class="exchange">{{ exchange === 'binance' ? 'B' : exchange === 'bitget' ? '↗' : '▦' }}</span><strong>{{ exchangeNames[exchange] }}</strong><span class="status-dot muted-dot"></span></div><div class="exchange-summary"><span>{{ accounts.accounts.filter(a => a.exchange === exchange).length }} 个连接配置</span><span class="tiny-tag">{{ accounts.accounts.some(a => a.exchange === exchange && a.checked_at) ? '有读取记录' : '待验证' }}</span></div><p>手动快照在账户页查看；持续同步待接入</p></article></div></section></template>
